<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
try {
 $root=realpath(dirname(__DIR__));
 if($root!=='/var/www/vhosts/shalean.com/faraios.com/_accounts-preview')throw new RuntimeException('Preview path mismatch');
 $live=dirname($root).'/account';$account=$root.'/account';$private='/var/www/vhosts/shalean.com/private/faraios-account';
 $payload=json_decode(gzdecode(base64_decode('')),true,512,JSON_THROW_ON_ERROR);
 $ops=json_decode(gzdecode(base64_decode('')),true,512,JSON_THROW_ON_ERROR);
 $expected=json_decode('{"core.php":"a533ff0b325a58102649652235e5732ef9c68cf21553132a1c3373b0a57d3b00","index.php":"ae4b3a8ad00fbc1629748458b1a7a5b4dec2189241856d85b8897cc58e9b2588"}',true,512,JSON_THROW_ON_ERROR);
 $action=getopt('',['action:'])['action']??'inspect';
 $liveBefore=[];foreach(glob($live.'/*.php') as $p)$liveBefore[basename($p)]=hash_file('sha256',$p);
 $configBefore=[];foreach(['config.php','production.php'] as $n)$configBefore[$n]=hash_file('sha256',$private.'/'.$n);
 $replaced=[];$current=[];foreach(['core.php','index.php','context.php','delegated.php'] as $n)$current[$n]=is_file($account.'/'.$n)?hash_file('sha256',$account.'/'.$n):null;
 if($action==='inspect'){echo json_encode(['status'=>'preview_inspected','current'=>$current,'expected'=>$expected,'live_hashes'=>$liveBefore,'config_hashes'=>$configBefore])."\n";exit;}
 if($action!=='install')throw new RuntimeException('Unknown action');
 foreach($expected as $n=>$hash)if($current[$n]!==$hash)throw new RuntimeException('Preview source drift: '.$n);
 foreach(['context.php','delegated.php'] as $n)if($current[$n]!==null)throw new RuntimeException('Unexpected existing preview route');
 $backup=$private.'/sc04-preview-'.gmdate('Ymd-His');if(!mkdir($backup,0700))throw new RuntimeException('Backup directory unavailable');
 foreach($current as $n=>$hash)if($hash!==null){if(!copy($account.'/'.$n,$backup.'/'.$n)||!chmod($backup.'/'.$n,0600))throw new RuntimeException('Application backup failed');}
 foreach($payload as $n=>$item){$raw=base64_decode($item['bytes'],true);if($raw===false||hash('sha256',$raw)!==$item['sha256'])throw new RuntimeException('Payload integrity failed');if(file_put_contents($account.'/'.$n.'.sc04-new',$raw,LOCK_EX)===false)throw new RuntimeException('Stage write failed');chmod($account.'/'.$n.'.sc04-new',0644);}
 $opdir=$private.'/sc04-ops';if(file_exists($opdir)||!mkdir($opdir,0700))throw new RuntimeException('Operations destination unavailable');
 foreach($ops as $n=>$bytes){$p=$opdir.'/'.$n;if(file_put_contents($p,base64_decode($bytes,true),LOCK_EX)===false||!chmod($p,0600))throw new RuntimeException('Operations adapter write failed');}
 // Prepare all bytes first, install common lookup last; originals are retained.
 foreach(['context.php','delegated.php','index.php','core.php'] as $n){if(!rename($account.'/'.$n.'.sc04-new',$account.'/'.$n))throw new RuntimeException('Preview replace failed');$replaced[]=$n;}
 foreach($liveBefore as $n=>$hash)if(hash_file('sha256',$live.'/'.$n)!==$hash)throw new RuntimeException('Live source changed');
 foreach($configBefore as $n=>$hash)if(hash_file('sha256',$private.'/'.$n)!==$hash)throw new RuntimeException('Private routing changed');
 foreach($payload as $n=>$item)if(hash_file('sha256',$account.'/'.$n)!==$item['sha256'])throw new RuntimeException('Installed checksum mismatch');
 echo json_encode(['status'=>'preview_installed','files'=>array_keys($payload),'backup'=>basename($backup),'live_unchanged'=>true,'private_config_unchanged'=>true,'hashes'=>array_map(fn($x)=>$x['sha256'],$payload)])."\n";
} catch(Throwable $e){if(isset($backup,$replaced)){foreach(array_reverse($replaced) as $n){if(is_file($backup.'/'.$n)){copy($backup.'/'.$n,$account.'/'.$n.'.sc04-restore');rename($account.'/'.$n.'.sc04-restore',$account.'/'.$n);}elseif(isset($current[$n])&&$current[$n]===null){unlink($account.'/'.$n);}}}fwrite(STDERR,$e->getMessage()."\n");exit(1);}
